"""P0 tests for ACK protocol own_text guard (F-01).

Verifies that:
1. own_text guard rejects self-echoes from role="unknown" lines.
2. The new reason names (own_text, not_agent_role) are used.
3. role_source is set when role="unknown" passes via own_text inference.
"""

import sys
from datetime import datetime
from pathlib import Path
import unittest

# Ensure the source tree is importable.
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from agent_evolution_protocol.coordination import ack_protocol

# The token is generated by token_for(event_id).
# token_for("EVT-AAAABBBBCCCC") == "AEP-ACK:EVT-AAAABBBBCCCC"
TOKEN = "AEP-ACK:EVT-AAAABBBBCCCC"

NOW = datetime.fromisoformat("2026-11-02T10:00:05Z")


class TestOwnTextGuard(unittest.TestCase):
    """The own_text guard is the core of F-01: role="unknown" lines must not
    satisfy an ACK check just because they contain the token -- they are our
    own request echoed back."""

    def test_own_text_rejects_self_echo_from_unknown_role(self):
        """A role="unknown" line containing the token must be rejected as
        own_text when the order body also contains that token."""
        order_body = f"Please reply with {TOKEN} when you understand."

        order = {
            "id": "order-1",
            "target": "qoder",
            "task": "AEP-TEST-1",
            "event_id": "EVT-AAAABBBBCCCC",
            "session_id": "4242",
            "created_at": "2026-11-02T10:00:00Z",
            "state": "MESSAGE_VISIBLE",
            "text": order_body,  # own_text
        }
        # role="unknown" line that is our own request (contains the token).
        events = [
            {
                "id": "evt-own",
                "role": "unknown",
                "direction": "unknown",
                "session_id": "4242",
                "recorded_at": "2026-11-02T10:00:01Z",
                "added_lines": [order_body],
            }
        ]

        verdict = ack_protocol.verdict(order, events=events, now=NOW)
        self.assertFalse(verdict["accepted"],
                         "Self-echo from role=unknown should be rejected as own_text")
        self.assertEqual(verdict["reason"], "own_text",
                         "Reason should be own_text, not not_assistant")

    def test_own_text_allows_unknown_role_when_not_self_echo(self):
        """A role="unknown" line that does NOT match the order body should
        pass the own_text guard and proceed to session/timestamp checks."""
        order_body = f"Please reply with {TOKEN} when you understand."

        order = {
            "id": "order-1",
            "target": "qoder",
            "task": "AEP-TEST-1",
            "event_id": "EVT-AAAABBBBCCCC",
            "session_id": "4242",
            "created_at": "2026-11-02T10:00:00Z",
            "state": "MESSAGE_VISIBLE",
            "text": order_body,
        }
        # role="unknown" line that is NOT our request (does not match body).
        events = [
            {
                "id": "evt-other",
                "role": "unknown",
                "direction": "unknown",
                "session_id": "4242",
                "recorded_at": "2026-11-02T10:00:01Z",
                "added_lines": [f"Some unrelated text with {TOKEN}"],
            }
        ]

        verdict = ack_protocol.verdict(order, events=events, now=NOW)
        self.assertTrue(verdict["accepted"],
                        "Non-self-echo from role=unknown should pass own_text guard")
        self.assertEqual(verdict["reason"], "",
                         "Accepted events should have empty reason")

    def test_not_agent_role_for_user_and_system(self):
        """role="user" and role="system" must be rejected as not_agent_role."""
        order = {
            "id": "order-1",
            "target": "qoder",
            "task": "AEP-TEST-1",
            "event_id": "EVT-AAAABBBBCCCC",
            "session_id": "4242",
            "created_at": "2026-11-02T10:00:00Z",
            "state": "MESSAGE_VISIBLE",
        }

        for role in ("user", "system"):
            events = [
                {
                    "id": f"evt-{role}",
                    "role": role,
                    "direction": "incoming",
                    "session_id": "4242",
                    "recorded_at": "2026-11-02T10:00:01Z",
                    "added_lines": [TOKEN],
                }
            ]
            verdict = ack_protocol.verdict(order, events=events, now=NOW)
            self.assertFalse(verdict["accepted"],
                             f"role={role} should be rejected")
            self.assertEqual(verdict["reason"], "not_agent_role",
                             f"Reason for role={role} should be not_agent_role")

    def test_rejection_names_are_correct(self):
        """All reason names in REJECTIONS must be present and documented."""
        # The actual set includes own_text, own_text_unavailable,
        # not_agent_role, not_assistant, own_text_outgoing, not_incoming,
        # foreign_session, session_unknown, stale, no_timestamp
        expected_keys = {
            "own_text",
            "own_text_unavailable",
            "not_agent_role",
            "not_assistant",
            "own_text_outgoing",
            "not_incoming",
            "foreign_session",
            "session_unknown",
            "stale",
            "no_timestamp",
        }
        self.assertEqual(set(ack_protocol.REJECTIONS.keys()), expected_keys,
                         "REJECTIONS must have the documented reasons")

    def test_verdict_carries_role_source_for_unknown(self):
        """When role="unknown" passes via own_text inference, the verdict
        should carry role_source so a supervisor can see how it was decided."""
        order = {
            "id": "order-1",
            "target": "qoder",
            "task": "AEP-TEST-1",
            "event_id": "EVT-AAAABBBBCCCC",
            "session_id": "4242",
            "created_at": "2026-11-02T10:00:00Z",
            "state": "MESSAGE_VISIBLE",
            "text": "Please reply with " + TOKEN,
        }
        events = [
            {
                "id": "evt-other",
                "role": "unknown",
                "direction": "unknown",
                "session_id": "4242",
                "recorded_at": "2026-11-02T10:00:01Z",
                "added_lines": [f"Some other text with {TOKEN}"],
            }
        ]

        verdict = ack_protocol.verdict(order, events=events, now=NOW)
        self.assertTrue(verdict["accepted"])
        self.assertIsNotNone(verdict["evidence"],
                             "evidence should exist for an accepted event")
        self.assertEqual(verdict["evidence"]["role_source"], "inferred_absent_own_text",
                         "role_source should be set in evidence when role=unknown passes via own_text inference")


if __name__ == "__main__":
    unittest.main()
